export function Gauge({
  value = {{value}},
  label = "{{label}}",
  zone = "{{zone}}",
  accent = "{{accent}}",
}) {
  const outline = {
    safe: "3px solid #241430",
    warning: "3px dashed #241430",
    critical: "3px dotted #241430",
  }[zone] ?? "3px solid #241430";
  return (
    <div role="img" aria-label={`Gauge showing ${label}: ${value} percent, ${zone} zone`}
      style={{ fontFamily: "system-ui, sans-serif", color: "#241430", maxWidth: 260, textAlign: "center", fontSize: 14 }}>
      <div style={{
        width: 160, height: 160, margin: "0 auto", borderRadius: "50%", position: "relative",
        background: `conic-gradient(${accent} ${value * 3.6}deg, #24143022 0)`,
        outline, outlineOffset: 3,
      }}>
        <div style={{ position: "absolute", inset: 25, borderRadius: "50%", background: "#FAF7F2",
          display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center" }}>
          <span style={{ fontSize: 28, fontWeight: 700 }}>{value}<span style={{ fontSize: 16, fontWeight: 500, marginLeft: 1 }}>%</span></span>
          <span style={{ fontSize: 12, color: "#241430aa", marginTop: 2 }}>{label}</span>
        </div>
      </div>
      <div aria-hidden="true" style={{ display: "flex", justifyContent: "space-between", maxWidth: 200, margin: "14px auto 0",
        paddingTop: 8, borderTop: "2px solid #24143033", fontSize: 10, color: "#241430aa" }}>
        <span>0%</span><span>25%</span><span>50%</span><span>75%</span><span>100%</span>
      </div>
      <p style={{ margin: "10px 0 0", fontSize: 13, fontWeight: 600, textTransform: "capitalize" }}>Zone: {zone}</p>
    </div>
  );
}
